function buildCuisineRecipes(cuisine) {
  const cuisineTemplates = templates[cuisine];
  if (!cuisineTemplates) return {};

  const recipes = {};
  const servingsCycle = [2, 2, 4, 3, 6];

  cuisineTemplates.forEach((template, index) => {
    const perServing = template.nutritionPerServing;
    const servings = servingsCycle[index % servingsCycle.length];

    const chefCount = Math.min(template.directions.length, 4);
    const directions = template.directions.map((direction, directionIndex) => ({
      ...direction,
      chef: (directionIndex % chefCount) + 1,
    }));

    recipes[`seed-${cuisine}-${index + 1}`] = {
      name: template.name,
      cuisine,
      diet: template.diet,
      timeCategory: template.timeCategory,
      cookingTime: template.cookingTime,
      servings,
      likes: template.likes,
      yourIngredients: template.yourIngredients,
      extraIngredients: template.extraIngredients,
      directions,
      nutritionPerServing: perServing,
      nutritionTotal: {
        energy: perServing.energy * servings,
        protein: perServing.protein * servings,
        carbs: perServing.carbs * servings,
        fat: perServing.fat * servings,
      },
      createdAt: Date.now() - index * 1000,
    };
  });

  return recipes;
}

function buildAllRecipes() {
  const recipes = {};
  for (const cuisine of Object.keys(templates)) {
    Object.assign(recipes, buildCuisineRecipes(cuisine));
  }
  return recipes;
}

const CUISINES = Object.keys(templates);

module.exports = { templates, CUISINES, RECIPES_PER_CUISINE, buildCuisineRecipes, buildAllRecipes };
